// base64StdEncoding is the standard (padded) base64 that the browser's
// `Authorization: Basic <b64>` header uses (RFC 7617).
func base64StdEncoding(s string) string { return base64.StdEncoding.EncodeToString([]byte(s)) }

// hexEncode is a tiny test-only helper.
func hexEncode(b []byte) string { return hex.EncodeToString(b) }

// TestPBKDF2KnownVector cross-validates the pure-stdlib PBKDF2-HMAC-SHA256
// KDF against a reference value generated by an independent implementation
// (Python 3 hashlib.pbkdf2_hmac). This pins the KDF so a future refactor
// that changes the derivation would immediately fail the suite.
//
//	pass   = "admin"
//	salt   = 0x000102...0e0f (16 bytes)
//	iterations = 210000
//	dklen  = 32
//	=> digest = e3c9535d61b6a4a44561ad950d221ad64f62349fe4a5ec325f63d2271d5e8394
func TestPBKDF2KnownVector(t *testing.T) {
	salt := []byte{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f}
	got := pbkdf2HMACSHA256([]byte("admin"), salt, 210000)
	want := "e3c9535d61b6a4a44561ad950d221ad64f62349fe4a5ec325f63d2271d5e8394"
	if gotHex := hexEncode(got); gotHex != want {
		t.Fatalf("pbkdf2HMACSHA256 = %q, want %q (KDF regression)", gotHex, want)
	}
}

// TestHashAndParseVerifier round-trips: HashBasicAuthPassword produces a
// document that ParseVerifier accepts and that VerifyCandidatePassword
// validates for the right password but rejects for the wrong one.
func TestHashAndParseVerifier(t *testing.T) {
	pass, err := GenerateBasicAuthPassword()
	if err != nil {
		t.Fatal(err)
	}
	doc, err := HashBasicAuthPassword(DefaultBasicAuthUsername, pass)
	if err != nil {
		t.Fatal(err)
	}
	user, iter, salt, digest, err := ParseVerifier(doc)
	if err != nil {
		t.Fatal(err)
	}
	if user != DefaultBasicAuthUsername {
		t.Errorf("user = %q, want %q", user, DefaultBasicAuthUsername)
	}
	if !VerifyCandidatePassword(user, pass, iter, salt, digest) {
		t.Error("correct password did not verify")
	}
	if VerifyCandidatePassword(user, pass+"x", iter, salt, digest) {
		t.Error("wrong password verified (should not)")
	}
	// NOTE: VerifyCandidatePassword deliberately does NOT check the username
	// (that is the BasicAuthenticator's job, see TestNewBasicAuthenticatorFrom
	// ... / TestServerRoutesRequireBasicAuth) — a valid password digest
	// verifies regardless of the user string passed here.
}

// TestHashBasicAuthPasswordSaltsConfirms that two hashes of the same
// password differ (fresh salt each call) — a property a verifier must have.
func TestHashBasicAuthPasswordSalts(t *testing.T) {
	a, err := HashBasicAuthPassword("admin", "same-pass")
	if err != nil {
		t.Fatal(err)
	}
	b, err := HashBasicAuthPassword("admin", "same-pass")
	if err != nil {
		t.Fatal(err)
	}
	if a == b {
		t.Error("two hashes of the same password are identical (no salting)")
	}
}

// TestParseVerifierRejects covers the fail-closed parse paths.
func TestParseVerifierRejects(t *testing.T) {
	cases := map[string]string{
		"empty":         "",
		"not json":      "hello",
		"wrong version": `{"v":99,"user":"admin","iter":210000,"saltHex":"000102030405060708090a0b0c0d0e0f","digestHex":"00"}`,
		"empty user":    `{"v":1,"user":"","iter":210000,"saltHex":"000102030405060708090a0b0c0d0e0f","digestHex":"00"}`,
		"bad iter":      `{"v":1,"user":"admin","iter":0,"saltHex":"000102030405060708090a0b0c0d0e0f","digestHex":"00"}`,
		"bad salt":      `{"v":1,"user":"admin","iter":210000,"saltHex":"zz","digestHex":"00"}`,
		"bad digest":    `{"v":1,"user":"admin","iter":210000,"saltHex":"000102030405060708090a0b0c0d0e0f","digestHex":"00"}`,
	}
	for name, doc := range cases {
		t.Run(name, func(t *testing.T) {
			if _, _, _, _, err := ParseVerifier(doc); err == nil {
				t.Errorf("ParseVerifier(%q) = nil error, want fail-closed error", doc)
			}
		})
	}
}

// TestGenerateRecoveryTokenRoundTrip proves the recovery token carries
// (user, iter, salt, digest) and decodes back to a verifier that still
// validates the original password — WITHOUT the plaintext ever travelling.
func TestGenerateRecoveryTokenRoundTrip(t *testing.T) {
	pass, _ := GenerateBasicAuthPassword()
	doc, _ := HashBasicAuthPassword(DefaultBasicAuthUsername, pass)
	user, iter, salt, digest, err := ParseVerifier(doc)
	if err != nil {
		t.Fatal(err)
	}
	tok := GenerateRecoveryToken(user, iter, salt, digest)
	rUser, rIter, rSalt, rDigest, ok := DecodeRecoveryToken(tok)
	if !ok {
		t.Fatal("recovery token failed to decode")
	}
	if rUser != user || rIter != iter {
		t.Errorf("decoded user/iter = %q/%d, want %q/%d", rUser, rIter, user, iter)
	}
	if !VerifyCandidatePassword(rUser, pass, rIter, rSalt, rDigest) {
		t.Error("password recovered from token did not verify")
	}
	if VerifyCandidatePassword(rUser, pass+"x", rIter, rSalt, rDigest) {
		t.Error("wrong password verified against recovered verifier")
	}
	// The token must NOT contain the plaintext password (it only carries the
	// salted digest + salt + iteration count).
	if strings.Contains(tok, pass) {
		t.Error("recovery token embeds the plaintext password")
	}
}

// TestDecodeRecoveryTokenRejects covers malformed tokens.
func TestDecodeRecoveryTokenRejects(t *testing.T) {
	for _, tok := range []string{"", "not-base64", "AAAA", "!!"} {
		if _, _, _, _, ok := DecodeRecoveryToken(tok); ok {
			t.Errorf("DecodeRecoveryToken(%q) = ok, want fail", tok)
		}
	}
}

// TestNewBasicAuthenticatorFromVerifier constructs an authenticator directly
// from an inline verifier and checks the full decision matrix.
func newBasicForTest(t *testing.T, user, pass string) *BasicAuthenticator {
	t.Helper()
	doc, err := HashBasicAuthPassword(user, pass)
	if err != nil {
		t.Fatal(err)
	}
	a, err := NewBasicAuthenticator(BasicAuthConfig{Verifier: doc})
	if err != nil {
		t.Fatal(err)
	}
	return a
}

func TestNewBasicAuthenticatorFromVerifier(t *testing.T) {
	auth := newBasicForTest(t, "admin", "secret-pass")

	tests := []struct {
		name   string
		user   string
		pass   string
		header string
		want   int
	}{
		{"no header", "x", "y", "", http.StatusUnauthorized},
		{"wrong username", "root", "secret-pass", basicHeader("root", "secret-pass"), http.StatusUnauthorized},
		{"wrong password", "admin", "nope", basicHeader("admin", "nope"), http.StatusUnauthorized},
		{"correct", "admin", "secret-pass", basicHeader("admin", "secret-pass"), http.StatusOK},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodGet, "/api/v1/health", nil)
			if tc.header != "" {
				req.Header.Set("Authorization", tc.header)
			}
			_, err := auth.Authenticate(req)
			if tc.want == http.StatusOK {
				if err != nil {
					t.Fatalf("Authenticate = err %v, want nil (success)", err)
				}
				return
			}
			var he *httpError
			if asHTTPError(err, &he) == false || he.Code != tc.want {
				t.Fatalf("Authenticate = %v, want 401 httpError", err)
			}
			// Every 401 on the Basic path must carry the WWW-Authenticate
			// challenge so the browser prompts.
			if he.Www == "" {
				t.Error("401 from Basic auth has no WWW-Authenticate challenge")
			}
		})
	}
}

// TestBasicAuthWWWChallengeShape pins the exact challenge string the spec
// requires: `Basic realm="TunnelDash", charset="UTF-8"`.
func TestBasicAuthWWWChallengeShape(t *testing.T) {
	auth := newBasicForTest(t, "admin", "p")
	req := httptest.NewRequest(http.MethodGet, "/x", nil)
	_, err := auth.Authenticate(req)
	var he *httpError
	if !asHTTPError(err, &he) {
		t.Fatal("expected a 401 httpError")
	}
	want := `Basic realm="TunnelDash", charset="UTF-8"`
	if he.Www != want {
		t.Errorf("WWW-Authenticate = %q, want %q", he.Www, want)
	}
}

// TestNewBasicAuthenticatorRejectsEmpty ensures an empty config fails
// closed (a TLS build must not silently run unauthenticated).
func TestNewBasicAuthenticatorRejectsEmpty(t *testing.T) {
	if _, err := NewBasicAuthenticator(BasicAuthConfig{}); err == nil {
		t.Error("NewBasicAuthenticator with empty config must fail closed")
	}
}

// TestBasicAuthenticatorUserOverrideConflict ensures a UserOverride that
// disagrees with the verifier is rejected (fail closed).
func TestBasicAuthenticatorUserOverrideConflict(t *testing.T) {
	doc, _ := HashBasicAuthPassword("admin", "p")
	if _, err := NewBasicAuthenticator(BasicAuthConfig{Verifier: doc, UserOverride: "root"}); err == nil {
		t.Error("conflicting UserOverride must fail")
	}
}

// TestLoadBasicAuthenticatorFromEnv reads the SPLIT_TUNNELDASH_CREDENTIALS
// file and loads the authenticator; a missing/unreadable file yields the
// (nil, false) fall-through.
func TestLoadBasicAuthenticatorFromEnv(t *testing.T) {
	t.Run("load from file", func(t *testing.T) {
		dir := t.TempDir()
		pass, _ := GenerateBasicAuthPassword()
		doc, _ := HashBasicAuthPassword("admin", pass)
		p := filepath.Join(dir, "credentials")
		if err := os.WriteFile(p, []byte(doc+"\n"), 0600); err != nil {
			t.Fatal(err)
		}
		t.Setenv(EnvDashCredentials, p)
		a, ok := LoadBasicAuthenticatorFromEnv()
		if !ok || a == nil {
			t.Fatalf("LoadBasicAuthenticatorFromEnv = (%v,%v), want success", a, ok)
		}
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.SetBasicAuth("admin", pass)
		if _, err := a.Authenticate(req); err != nil {
			t.Errorf("Authenticate with correct creds = %v, want nil", err)
		}
	})

	t.Run("missing file falls through", func(t *testing.T) {
		t.Setenv(EnvDashCredentials, "/no/such/file")
		if a, ok := LoadBasicAuthenticatorFromEnv(); ok || a != nil {
			t.Errorf("unresolvable credential file = (%v,%v), want (nil,false)", a, ok)
		}
	})

	t.Run("unset -> not configured", func(t *testing.T) {
		t.Setenv(EnvDashCredentials, "")
		if DashCredentialsConfigured() {
			t.Error("DashCredentialsConfigured() with empty var = true, want false")
		}
	})
}

// TestLoadBasicAuthenticatorFromEnvErr pins the bounded error detail: an
// unresolvable credential file (missing / not a valid verifier) yields a
// non-nil error that names the cause but NEVER leaks the verifier contents
// or a password. A valid file yields (auth, nil); an unset var yields
// (nil, nil).
func TestLoadBasicAuthenticatorFromEnvErr(t *testing.T) {
	t.Run("unset -> no error, no auth", func(t *testing.T) {
		t.Setenv(EnvDashCredentials, "")
		a, err := LoadBasicAuthenticatorFromEnvErr()
		if a != nil || err != nil {
			t.Errorf("unset = (%v, %v), want (nil, nil)", a, err)
		}
	})

	t.Run("valid file -> auth, no error", func(t *testing.T) {
		dir := t.TempDir()
		pass, _ := GenerateBasicAuthPassword()
		doc, _ := HashBasicAuthPassword("admin", pass)
		p := filepath.Join(dir, "credentials")
		if err := os.WriteFile(p, []byte(doc+"\n"), 0600); err != nil {
			t.Fatal(err)
		}
		t.Setenv(EnvDashCredentials, p)
		a, err := LoadBasicAuthenticatorFromEnvErr()
		if a == nil || err != nil {
			t.Fatalf("valid file = (%v, %v), want (auth, nil)", a, err)
		}
	})

	t.Run("missing file -> bounded error naming the cause", func(t *testing.T) {
		t.Setenv(EnvDashCredentials, "/no/such/verifier/file")
		a, err := LoadBasicAuthenticatorFromEnvErr()
		if a != nil || err == nil {
			t.Fatalf("missing file = (%v, %v), want (nil, error)", a, err)
		}
		// The detail must be diagnosable (name the field/cause) but must NOT
		// leak a path-to-digest value or a password.
		if !strings.Contains(err.Error(), "read") && !strings.Contains(err.Error(), "no such file") {
			t.Errorf("error lacks useful detail: %v", err)
		}
	})

	t.Run("malformed verifier -> bounded parse error, no digest leak", func(t *testing.T) {
		dir := t.TempDir()
		p := filepath.Join(dir, "credentials")
		if err := os.WriteFile(p, []byte("not-json-at-all"), 0600); err != nil {
			t.Fatal(err)
		}
		t.Setenv(EnvDashCredentials, p)
		_, err := LoadBasicAuthenticatorFromEnvErr()
		if err == nil {
			t.Fatal("malformed verifier = nil error, want a parse error")
		}
		// The raw malformed document must NOT be echoed into the error.
		if strings.Contains(err.Error(), "not-json-at-all") {
			t.Errorf("error leaked the verifier contents: %v", err)
		}
	})
}

// TestDashCredentialsConfigured pins the fail-closed predicate.
func TestDashCredentialsConfigured(t *testing.T) {
	t.Setenv(EnvDashCredentials, "/some/path")
	if !DashCredentialsConfigured() {
		t.Error("DashCredentialsConfigured() = false, want true (path set)")
	}
}

// TestServerRoutesRequireBasicAuth wires a TLS-shaped server (basePath +
// security headers) with a BasicAuthenticator and proves:
//   - UI GET and API GET succeed WITH the credentials,
//   - both fail with 401 + WWW-Authenticate challenge WITHOUT them.
//
// This is the browser flow: prompt once, then auto-send on every request.
func TestServerRoutesRequireBasicAuth(t *testing.T) {
	cfg := secureTestConfig()
	pass, _ := GenerateBasicAuthPassword()
	doc, _ := HashBasicAuthPassword("admin", pass)
	auth, err := NewBasicAuthenticator(BasicAuthConfig{Verifier: doc})
	if err != nil {
		t.Fatal(err)
	}
	cache := NewCache(cfg)
	audit := NewAuditLog(cfg.MaxAudit)
	s := NewTLSServer(cfg, cache, audit, nil, auth)
	h := s.Router()
	bp := cfg.BasePath() // "/<32-hex>/"

	// No credentials: UI + API both 401 with the challenge.
	for _, path := range []string{bp, bp + "api/v1/health"} {
		rr := get(h, path)
		if rr.Code != http.StatusUnauthorized {
			t.Errorf("%s without creds: status = %d, want 401", path, rr.Code)
		}
		if got := rr.Header().Get("WWW-Authenticate"); got != `Basic realm="TunnelDash", charset="UTF-8"` {
			t.Errorf("%s WWW-Authenticate = %q, want the Basic challenge", path, got)
		}
	}

	// With correct credentials: UI + API both 200 (the browser re-sends the
	// cached Basic auth automatically on every same-origin request).
	withCreds := func(method, path, user, pass string) *httptest.ResponseRecorder {
		req := httptest.NewRequest(method, path, nil)
		req.SetBasicAuth(user, pass)
		rr := httptest.NewRecorder()
		h.ServeHTTP(rr, req)
		return rr
	}
	if rr := withCreds(http.MethodGet, bp, "admin", pass); rr.Code != http.StatusOK {
		t.Errorf("UI GET with creds = %d, want 200; body=%s", rr.Code, rr.Body.String())
	}
	if rr := withCreds(http.MethodGet, bp+"api/v1/health", "admin", pass); rr.Code != http.StatusOK {
		t.Errorf("API GET with creds = %d, want 200; body=%s", rr.Code, rr.Body.String())
	}
	// Wrong password still 401 even on the API.
	if rr := withCreds(http.MethodGet, bp+"api/v1/health", "admin", pass+"x"); rr.Code != http.StatusUnauthorized {
		t.Errorf("API GET with wrong password = %d, want 401", rr.Code)
	}
}

// TestLoopbackBasicAuthStillOpenForLocalDev confirms that a non-TLS local
// build keeps its no-credential default (the loopback authenticator), so
// the documented dev behavior is unchanged. Basic auth is only reachable on
// the server-hosted TLS surface.
func TestLoopbackNoCredentialDefault(t *testing.T) {
	cfg := DefaultConfig() // no TLS
	s := newTestServer(cfg)
	rr := doRequest(t, s, http.MethodGet, "/api/v1/health", "")
	if rr.Code != http.StatusOK {
		t.Errorf("loopback local build health = %d, want 200 (no-credential default preserved)", rr.Code)
	}
}

// helpers -----------------------------------------------------------------

// basicHeader builds an `Authorization: Basic base64(user:pass)` value.
func basicHeader(user, pass string) string {
	return "Basic " + base64StdEncoding(user+":"+pass)
}
